name: Checks

on:
  push:
    branches: [main]
  pull_request:

jobs:
  lockfile-validation:
    runs-on: ubuntu-latest
    steps:
      - name: Checkout repository
        uses: actions/checkout@v4

      - name: Setup Node.js 22
        uses: actions/setup-node@v4
        with:
          node-version: 22
          cache: pnpm

      - name: Setup pnpm 9
        uses: pnpm/action-setup@v4
        with:
          version: 9
          run_install: false

      - name: Install dependencies (include devDependencies)
        run: pnpm install --include-dev

      - name: Install js-yaml globally
        run: npm install -g js-yaml

      - name: Validate lockfile devDependencies
        run: |
          node - <<'NODE'
          const fs = require('fs');
          const yaml = require('js-yaml');
          const lockPath = 'pnpm-lock.yaml';
          if (!fs.existsSync(lockPath)) {
            console.error(`Lockfile ${lockPath} not found`);
            process.exit(1);
          }
          const lock = yaml.load(fs.readFileSync(lockPath, 'utf8'));
          const problematic = [];
          for (const [pkgPath, pkg] of Object.entries(lock.packages || {})) {
            if (pkgPath !== '/' && pkg.devDependencies && Object.keys(pkg.devDependencies).length > 0) {
              problematic.push(pkgPath);
            }
          }
          if (problematic.length) {
            console.error('Found devDependencies in lockfile for non-isolated packages:');
            problematic.forEach(p => console.error('  -', p));
            process.exit(1);
          }
          console.log('No problematic devDependencies found in lockfile.');
          NODE
        shell: bash
```

